'use strict';

// MODULES //

var tape = require( 'tape' );
var concat = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof concat, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function concatenates two strings', function test( t ) {
	var expected;
	var actual;
	var str1;
	var str2;

	str1 = 'hello';
	str2 = 'world';
	expected = 'helloworld';
	actual = concat( str1, str2 );
	t.strictEqual( actual, expected, 'concatenates strings' );

	str1 = 'foo';
	str2 = 'bar';
	expected = 'foobar';
	actual = concat( str1, str2 );
	t.strictEqual( actual, expected, 'concatenates strings' );

	str1 = '';
	str2 = 'baz';
	expected = 'baz';
	actual = concat( str1, str2 );
	t.strictEqual( actual, expected, 'handles empty first string' );

	str1 = 'qux';
	str2 = '';
	expected = 'qux';
	actual = concat( str1, str2 );
	t.strictEqual( actual, expected, 'handles empty second string' );

	str1 = '';
	str2 = '';
	expected = '';
	actual = concat( str1, str2 );
	t.strictEqual( actual, expected, 'handles both empty strings' );

	str1 = 'a';
	str2 = 'b';
	expected = 'ab';
	actual = concat( str1, str2 );
	t.strictEqual( actual, expected, 'handles single character strings' );

	str1 = 'beep';
	str2 = ' boop';
	expected = 'beep boop';
	actual = concat( str1, str2 );
	t.strictEqual( actual, expected, 'handles strings with spaces' );

	str1 = '$**_';
	str2 = 'beep_**$';
	expected = '$**_beep_**$';
	actual = concat( str1, str2 );
	t.strictEqual( actual, expected, 'handles strings with special characters' );

	t.end();
});
